      function weeklyScores(key){var games=editions[String(key)]&&editions[String(key)].games,scores=[];if(!games){return scores}games.forEach(function(game){scores.push({team:game[0],points:game[1]},{team:game[2],points:game[3]})});return scores}
      function weeklyMedian(key){var scores=weeklyScores(key).map(function(score){return score.points}).sort(function(a,b){return a-b});return scores.length===12?(scores[5]+scores[6])/2:null}
      function recordsForEdition(key,mode){
        var records={},through=Number(key)-(mode==='preview'?1:0),week,games,scores,median;
        Object.keys(teamAvatars).forEach(function(team){records[team]={wins:0,losses:0}});
        for(week=1;week<=through;week+=1){
          games=editions[String(week)]&&editions[String(week)].games;
          if(!games){continue}
          games.forEach(function(game){
            if(game[1]!==game[3]){
              if(game[1]>game[3]){records[game[0]].wins+=1;records[game[2]].losses+=1}
              else{records[game[2]].wins+=1;records[game[0]].losses+=1}
            }
          });
          scores=weeklyScores(week);
          median=weeklyMedian(week);
          scores.forEach(function(score){
            if(score.points>median){records[score.team].wins+=1}
            else if(score.points<median){records[score.team].losses+=1}
          });
        }
        return records;
      }
      function editionRecord(team,key,mode){var record=recordsForEdition(key,mode)[team];return record?record.wins+'–'+record.losses:'0–0'}
